
/* ================= shared data ================= */
const RED_LINES=[
 {name:"💨 風速上限",lim:"≤ 12.5 m/s",note:"VEMA 原廠手冊值，非通用教材的 22 m/s"},
 {name:"📐 展梯前傾斜",lim:"原廠 ±0.3°／教材 ±0.2°",note:"自動平衡完成後才可展梯"},
 {name:"🦿 單腳地面壓力",lim:"≤ 150 kN",note:"一律使用墊板傳力"},
 {name:"↔️ 平台側向力",lim:"≤ 400 N",note:"跨越、探身、繩索作業須管理"},
 {name:"🎯 水砲操作",lim:"平台完全置中",note:"任務切換前先重新置中"},
 {name:"🖥️ 載重限額",lim:"車載即時螢幕",note:"500 kg 是能力上限，非任何姿態皆可用"},
];
function windStat(v){return v>=12.5?"red":v>=10?"amber":"ok"}
function tiltStat(v){v=Math.abs(v);return v>=0.2?"red":v>=0.15?"amber":"ok"}
function legStat(v){return v>=150?"red":v>=140?"amber":"ok"}
function scbaStat(v){return v<=50?"red":v<=60?"amber":"ok"}
const cls=s=>s==="ok"?"":s;
function renderGauges(d){
  const col=s=>s==="red"?"var(--red)":s==="amber"?"var(--amber)":"var(--green)";
  const rows=[
    {n:"💨 風速",v:d.wind.toFixed(1),u:"m/s",s:windStat(d.wind),fill:Math.min(d.wind/12.5,1),tick:1,dl:d.wind-12.5,du:"vs 12.5",dp:1},
    {n:"📐 傾斜",v:d.tilt.toFixed(2),u:"°",s:tiltStat(d.tilt),fill:Math.min(Math.abs(d.tilt)/0.3,1),tick:1,dl:d.tilt-0.3,du:"vs ±0.3",dp:2},
    {n:"🦿 單腳壓力",v:Math.round(d.leg),u:"kN",s:legStat(d.leg),fill:Math.min(d.leg/150,1),tick:1,dl:d.leg-150,du:"vs 150",dp:0},
    {n:"🫁 SCBA",v:Math.round(d.scba),u:"%",s:scbaStat(d.scba),fill:Math.min(d.scba/100,1),tick:0.5,dl:d.scba-50,du:"vs 50",dp:0},
  ];
  document.getElementById("gauges").innerHTML=rows.map(x=>{
    const arrow=x.dl>=0?"▲":"▼";const dv=Math.abs(x.dl).toFixed(x.dp);
    return `<div class="gauge"><div class="gl"><span class="name">${x.n}</span><span class="light ${cls(x.s)}"></span></div>
      <div class="val">${x.v}<small>${x.u}</small></div>
      <div class="meter"><i style="width:${(x.fill*100).toFixed(0)}%;background:${col(x.s)}"></i><b style="left:${(x.tick*100).toFixed(0)}%"></b></div>
      <div class="delta">${arrow} ${x.dl>=0?"+":"−"}${dv} ${x.du}</div></div>`;
  }).join("");
  const bad=[];
  if(windStat(d.wind)==="red")bad.push("風速達停止線");
  if(tiltStat(d.tilt)==="red")bad.push("傾斜超 ±0.3°");
  if(legStat(d.leg)==="red")bad.push("單腳達 150 kN");
  if(scbaStat(d.scba)==="red")bad.push("SCBA 達 50%");
  const near=[windStat(d.wind),tiltStat(d.tilt),legStat(d.leg),scbaStat(d.scba)].includes("amber");
  const sl=document.getElementById("statusline");
  if(bad.length){sl.className="statusline warn";sl.innerHTML="⚠️ 紅線："+bad.join("、")}
  else if(near){sl.className="statusline warn";sl.innerHTML="⚠️ 部分數值逼近紅線，密切監看"}
  else{sl.className="statusline ok";sl.innerHTML="✅ 各項數值在安全範圍內"}
}
function idleGauges(){renderGauges({wind:0,tilt:0,leg:0,scba:100});const s=document.getElementById("statusline");s.className="statusline ok";s.innerHTML="🛑 系統待命 · 尚未進入任務"}
function renderRedlines(){document.getElementById("redlines").innerHTML=RED_LINES.map(r=>`<details><summary><span>${r.name}</span><span class="lim">${r.lim}</span></summary><div class="body">${r.note}</div></details>`).join("")}

/* ================= screens ================= */
const SCREENS=["home","scen","sim","quiz","result"];
function show(id){SCREENS.forEach(s=>document.getElementById("screen-"+s).hidden=(s!==id))}

/* ================= SIMULATOR ================= */
const cv=document.getElementById("cv"), ctx=null;
let G={}, sim=null, raf=null, lastT=0;
const held={drive:0, ang:0, ext:0, rot:0, jib:0};

const SCEN=[
 {id:"rescue",tag:"人命救援",ic:"🚒",name:"情境①　A 面六樓陽台待救",page:"教材 p.8–12、p.20–23",
  kind:"rescue",wind:9,rise:0,bearing:0,startHeading:-34,allowNeg:false,targetHm:15,tree:5,collapse:0,below:0,
  intro:"駛入 A 面對準轉台中心、展腳架、轉台對準 A 面，升梯跨越行道樹把平台送上六樓陽台完成救援。",
  hint:"先升角讓梯臂跨越行道樹（水平瞄準）再伸長靠近陽台。"},
 {id:"wind",tag:"撤離判斷",ic:"🌬️",name:"情境②　強風逼近·必須退離",page:"教材 p.27、p.37",
  kind:"retreat",wind:10.2,rise:1.15,bearing:0,startHeading:-34,allowNeg:false,targetHm:15,tree:5,collapse:0,below:0,
  intro:"升空接近待救者，但風速一路爬升。破 12.5 m/s 停止線時，必須立即『緊急退離』收梯——未超機械上限，也可能因火煙環境必須立即撤離。",
  hint:"風速破 12.5 時，點『緊急退離』把梯臂全收才算安全。"},
 {id:"water",tag:"大型射水",ic:"💦",name:"情境③　大型射水·留倒塌區",page:"教材 p.14–15、p.46",
  kind:"water",wind:8,rise:0,bearing:-26,startHeading:6,allowNeg:false,targetHm:12,tree:0,collapse:1,below:0,
  intro:"車位留在倒塌區外，轉台對準相對安全的『建物轉角』（避開正面下風排煙側），平台完全置中後才可開砲。",
  hint:"轉台對準綠點（轉角），關節臂歸零使平台置中，才可開砲。"},
 {id:"bridge",tag:"特殊作業",ic:"🌉",name:"情境④　橋下負仰角救援",page:"教材 p.19",
  kind:"below",wind:6,rise:0,bearing:0,startHeading:-20,allowNeg:true,targetHm:-6,tree:0,collapse:0,below:1,
  intro:"目標低於車位平面。需用『負仰角＋關節臂』探到橋下邊坡——教材列為特殊作業，本分隊 33 車實際無法操作。",
  hint:"降到負仰角越過護欄，再用關節臂下折把平台送到河床邊坡。"},
];

function isDark(){return (document.documentElement.getAttribute("data-theme")||(matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"))==="dark"}
function palette(){ return isDark()
  ? {sky1:"#0e1a23",sky2:"#132a37",ground:"#16232c",road:"#22333f",lane:"#3c515f",
     bld:"#28353f",bld2:"#222e37",edge:"#3d4f5b",win:"#0f1d26",winLit:"#f3c24a",txt:"#c6d3db",sub:"#7d8d99",
     truck:"#e23a2c",truckDk:"#a5251d",glass:"#7fb4d6",boom:"#eab63a",boomDk:"#b98a24",steel:"#9fb0bc",
     pad:"#c9a24a",cone:"#f08a24",tree:"#2f6f43",tree2:"#245635",trunk:"#5a4630",zone:"#3ABE77",
     smoke:"rgba(150,158,168,.32)",river:"#153744",hatch:"#f0483a",mmBg:"#0c161d",water:"#6fc6ea"}
  : {sky1:"#cfe2f0",sky2:"#eaf3fa",ground:"#c7d2cb",road:"#8b9aa4",lane:"#e8eef2",
     bld:"#b9c4cc",bld2:"#a9b6bf",edge:"#8b99a3",win:"#7f97a6",winLit:"#ffd24a",txt:"#22323d",sub:"#5a6b76",
     truck:"#d8352a",truckDk:"#9e241c",glass:"#8fc0e0",boom:"#e0a92a",boomDk:"#a97e1e",steel:"#8496a2",
     pad:"#b98a2e",cone:"#e8791a",tree:"#4f9d63",tree2:"#3c7f4d",trunk:"#6b543a",zone:"#1E9E5B",
     smoke:"rgba(96,106,116,.28)",river:"#8fb8cf",hatch:"#d42e22",mmBg:"#eef3f6",water:"#3f9fd6"} }

function newScenario(sc){
  return { scen:sc, phase:"position", t0:0, time:0, truckX:0,
    wind:sc.wind, gust:0, tilt:0, outrig:0, scba:96,
    heading:sc.startHeading, mainAng:2, mainLen:4, jibAng:0, jibLen:4,
    exposed:false, windEvent:false, watering:false, retreating:false,
    rescued:false, success:false, _init:false };
}
function layout(){
  const W=cv.clientWidth, H=cv.clientHeight, dpr=Math.min(devicePixelRatio||1,2);
  cv.width=W*dpr; cv.height=H*dpr; ctx.setTransform(dpr,0,0,dpr,0,0);
  const sc=sim?sim.scen:SCEN[0];
  const groundY = sc.below ? H*0.52 : H-30;
  const ppm=(H-64)/(sc.below?30:24);
  const bldLeft=Math.min(W-96, W*0.66);
  const targetY=groundY - sc.targetHm*ppm;
  let targetX, coneX, idealReach=9;
  if(sc.below){ targetX=bldLeft+2*ppm; idealReach=7; coneX=targetX-idealReach*ppm; }
  else { targetX=bldLeft-0.6*ppm; coneX=targetX-idealReach*ppm; }
  const treeX=targetX-5*ppm, treeTop=groundY-(sc.tree||0)*ppm;
  const colRight=bldLeft-0.5*ppm, colLeft=bldLeft-7*ppm;
  G={W,H,dpr,groundY,ppm,bldLeft,targetX,targetY,treeX,treeTop,coneX,idealReach,colLeft,colRight,
     bridgeEdge:bldLeft-0.5*ppm, driveMin:W*0.05,
     driveMax: sc.collapse? colLeft-1.5*ppm : (sc.below? targetX-3.5*ppm : targetX-2.6*ppm),
     pivotYm:2.4};
  if(sim && !sim._init){ sim.truckX=W*0.10; sim._init=true; }
}
function pivot(){ return {x:sim.truckX, y:G.groundY-G.pivotYm*G.ppm}; }
function mainTip(){ const p=pivot(), a=sim.mainAng*Math.PI/180, L=sim.mainLen*G.ppm;
  return {x:p.x+Math.cos(a)*L, y:p.y-Math.sin(a)*L}; }
function tip(){ const m=mainTip(), ja=(sim.mainAng+sim.jibAng)*Math.PI/180, Lj=sim.jibLen*G.ppm;
  return {x:m.x+Math.cos(ja)*Lj, y:m.y-Math.sin(ja)*Lj}; }
function reachM(){ return (tip().x-pivot().x)/G.ppm; }
function heightM(){ return (G.groundY-tip().y)/G.ppm; }
function loadPct(){ return Math.max(0,Math.round(100-Math.abs(reachM())/12*58)); }
function segRectHit(p,q,rx,ry,rw,rh){
  const minx=Math.min(p.x,q.x),maxx=Math.max(p.x,q.x),miny=Math.min(p.y,q.y),maxy=Math.max(p.y,q.y);
  if(maxx<rx||minx>rx+rw||maxy<ry||miny>ry+rh) return false;
  for(let t=0;t<=1;t+=0.04){const x=p.x+(q.x-p.x)*t,y=p.y+(q.y-p.y)*t; if(x>=rx&&x<=rx+rw&&y>=ry&&y<=ry+rh)return true;}
  return false;
}
function treeRect(){ if(!sim.scen.tree)return null; const w=1.4*G.ppm; return {x:G.treeX-w,y:G.treeTop,w:2*w,h:G.groundY-G.treeTop}; }
function parapetRect(){ if(!sim.scen.below)return null; const w=0.35*G.ppm; return {x:G.bridgeEdge-w,y:G.groundY-1.5*G.ppm,w:2*w,h:1.5*G.ppm}; }
function hitBoom(r){ if(!r)return false; const p=pivot(),m=mainTip(),t=tip();
  return segRectHit(p,m,r.x,r.y,r.w,r.h)||segRectHit(m,t,r.x,r.y,r.w,r.h); }
function clearsObstacles(){ return !hitBoom(treeRect()) && !hitBoom(parapetRect()); }
function distToTargetM(){ const tp=tip(); return Math.hypot(tp.x-G.targetX,tp.y-G.targetY)/G.ppm; }
function inZone(){ return distToTargetM() < (sim.scen.kind==="water"?1.8:1.2); }
function aligned(){ return Math.abs(sim.heading - sim.scen.bearing) < 8; }

function simDash(){
  const deployed=sim.outrig>0.98;
  const leg = deployed ? 72+Math.abs(reachM())*4.6+Math.abs(sim.mainAng)*0.12 : 0;
  return {wind:sim.wind+sim.gust, tilt:sim.tilt, leg, scba:sim.scba};
}

const STEP_DEFS=[["01","選位"],["02","支撐"],["03","平衡"],["04","展梯"],["05","任務"],["06","撤收"]];
function stepIndex(){ return {position:0,support:1,balance:2,operate:3,"recover-run":5,recover:5,done:5}[sim.phase] ?? 0; }
function renderSteps(){
  const ci=stepIndex();
  document.getElementById("steps").innerHTML=STEP_DEFS.map((s,i)=>{
    let c="step"; if(i<ci||(sim.success&&i<=4))c+=" done"; else if(i===ci)c+=" on";
    return `<div class="${c}"><b>${s[0]}</b>${s[1]}</div>`;
  }).join("");
}

function renderControls(){
  const c=document.getElementById("controls"), p=sim.phase, sc=sim.scen;
  if(p==="position"){
    c.innerHTML=`
      <div class="ctlrow"><span class="lbl">駕駛</span>
        <button class="hbtn" data-hold="drive-1">◀ 駛近</button>
        <button class="hbtn" data-hold="drive+1">駛離 ▶</button></div>
      <button class="hbtn primary block" id="confirmPos" style="width:100%">✔ 確認車位（對準轉台中心）</button>
      <div class="keyhint">← →／A D 駕駛。將車頂轉台中心對準地面三角錐，可縮短伸距、保留荷重。${sc.collapse?"本情境車位須留在倒塌區外。":""}</div>`;
  } else if(p==="support"){
    c.innerHTML=`<button class="hbtn primary block" id="deployRig" style="width:100%">🦿 展開腳架與墊板</button>
      <div class="keyhint">腳架全伸並鋪墊板，系統自動平衡至 ±0.3° 內才可展梯（原廠手冊；教材 p.26、p.34 建議 ±0.2°）。</div>`;
  } else if(p==="operate"){
    const act = sc.kind==="water" ? "💦 開始射水" : "🧑‍🚒 完成救援移載";
    c.innerHTML=`
      <div class="ctlrow"><span class="lbl">轉台</span>
        <button class="hbtn" data-hold="rot+1">↺ 左旋</button>
        <button class="hbtn" data-hold="rot-1">右旋 ↻</button></div>
      <div class="ctlrow"><span class="lbl">仰角</span>
        <button class="hbtn" data-hold="ang+1">⤒ 升角</button>
        <button class="hbtn" data-hold="ang-1">⤓ 降角</button></div>
      <div class="ctlrow"><span class="lbl">伸縮</span>
        <button class="hbtn" data-hold="ext+1">⟺ 伸長</button>
        <button class="hbtn" data-hold="ext-1">⟻ 收回</button></div>
      <div class="ctlrow"><span class="lbl">關節臂</span>
        <button class="hbtn" data-hold="jib+1">⌐ 上折</button>
        <button class="hbtn" data-hold="jib-1">¬ 下折</button></div>
      <button class="hbtn go block" id="actBtn" style="width:100%" disabled>${act}</button>
      <div class="keyhint">Q／E 轉台、W／S 仰角、D／A 伸縮、R／F 關節臂。${sc.hint||""}</div>`;
  } else if(p==="recover"){
    c.innerHTML=`<button class="hbtn primary block" id="doRecover" style="width:100%">⟲ 收梯復歸並撤收腳架</button>
      <div class="keyhint">固定順序：伸縮臂全收 → 轉台回中央 → 降至支架 → 收腳架墊板（教材 p.47）。</div>`;
  } else { c.innerHTML=""; }
  wireControls();
}
function wireControls(){
  document.querySelectorAll("#controls [data-hold]").forEach(b=>{
    const code=b.dataset.hold; const which=code.replace(/[+-]1$/,""); const dir=code.endsWith("+1")?1:-1;
    const on=e=>{e.preventDefault(); held[which]=dir; b.classList.add("act");};
    const off=()=>{ if(held[which]===dir)held[which]=0; b.classList.remove("act");};
    b.addEventListener("pointerdown",on); b.addEventListener("pointerup",off);
    b.addEventListener("pointerleave",off); b.addEventListener("pointercancel",off);
  });
  const cp=document.getElementById("confirmPos"); if(cp)cp.onclick=()=>{ sim.phase="support"; coach(); renderControls(); renderSteps(); };
  const dr=document.getElementById("deployRig"); if(dr)dr.onclick=()=>{ sim.phase="balance"; };
  const ab=document.getElementById("actBtn"); if(ab)ab.onclick=doAction;
  const rv=document.getElementById("doRecover"); if(rv)rv.onclick=()=>{ sim.phase="recover-run"; };
}
function coach(msg,kind){ const el=document.getElementById("coach"), m=document.getElementById("coachMsg");
  el.className="coach"+(kind?(" "+kind):""); m.innerHTML=msg||coachDefault(); }
function coachDefault(){
  const sc=sim.scen;
  switch(sim.phase){
    case"position":return "把車頂<strong>轉台中心</strong>對準地面三角錐——戰術原點越準，伸距越短、可用荷重越高。"+(sc.collapse?"注意車位保留在<strong>倒塌區外</strong>。":"");
    case"support":return "車位確認。<strong>展開腳架與墊板</strong>把力安全傳到地面，單腳壓力不得達 150 kN。";
    case"balance":return "自動平衡中……傾斜收斂至 ±0.3° 內才可展梯（教材建議 ±0.2°）。";
    case"operate":return operateHint();
    case"recover":case"recover-run":return "開始撤收：伸縮臂全收 → 轉台回中央 → 降至支架 → 收腳架。";
    default:return "—";
  }
}
function operateHint(){
  const sc=sim.scen;
  if(!aligned())return "先<strong>旋轉轉台</strong>，把主俯視圖的指向線對準綠點目標立面（掃掠區內清空人員與管線）。";
  if(sc.kind==="water")return "轉台已對準安全轉角。把<strong>關節臂歸零讓平台完全置中</strong>、靠近目標窗口後即可開砲。";
  if(sc.kind==="below")return "降到<strong>負仰角</strong>越過護欄，再用<strong>關節臂下折</strong>把平台送到橋下河床邊坡。";
  if(sc.kind==="retreat")return "接近待救者。留意風速持續上升，隨時準備緊急退離。";
  return "先<strong>升角</strong>讓梯臂上緣跨越行道樹，再伸長把平台送進六樓陽台綠色救援區。";
}

function actionEnabled(){
  const sc=sim.scen, base=aligned()&&Math.abs(sim.tilt)<0.2&&(sim.wind+sim.gust)<12.5&&clearsObstacles()&&loadPct()>=45;
  if(sc.kind==="rescue") return base&&inZone()&&Math.abs(reachM())<=11.6;
  if(sc.kind==="below")  return aligned()&&Math.abs(sim.tilt)<0.2&&inZone()&&clearsObstacles()&&sim.mainAng<0&&loadPct()>=45;
  if(sc.kind==="water")  return base&&inZone()&&Math.abs(sim.jibAng)<6;
  if(sc.kind==="retreat")return sim.windEvent; // 緊急退離
  return false;
}
function doAction(){
  const sc=sim.scen;
  if(sc.kind==="water"){ sim.watering=true; endSuccess(waterPanel()); return; }
  if(sc.kind==="retreat" && sim.windEvent){ sim.retreating=true; sim.phase="recover-run";
    renderControls(); coach("🚨 緊急退離中：停止一切任務，梯臂全收、往上風側回收。","warn"); return; }
  if(sc.kind==="below"){ endSuccess(belowPanel()); return; }
  endSuccess(rescuePanel());          // rescue
}
function endSuccess(html){
  sim.rescued=true; sim.success=true; sim.time=(performance.now()-sim.t0)/1000; sim.phase="recover";
  renderControls(); renderSteps();
  coach("✔ 任務完成，開始依原廠順序撤收；落地後完成 <strong>PAR 清點</strong>。","ok");
  document.getElementById("simWin").innerHTML=html; wireWin();
}
function stat(k,l){ return `<div><div class="k">${k}</div><div class="l">${l}</div></div>`; }
function winBtns(){ return `<div class="wbtns">
  <button class="hbtn primary" id="winAgain">↻ 再演練一次</button>
  <button class="hbtn" id="winScen">🚒 換情境</button>
  <button class="hbtn" id="winQuiz">📋 戰術決策考核</button></div>`; }
function rescuePanel(){ return `<div class="win"><h3>🎉 救援成功</h3>
  <p>平台以最短伸距安全靠近目標，全程未觸及紅線。依生命危險排序、平台落地有安全出入口。</p>
  <div class="wstats">${stat(sim.time.toFixed(1)+"s","作業用時")}${stat(reachM().toFixed(1)+" m","水平伸距")}${stat(heightM().toFixed(1)+" m","平台高度")}${stat(loadPct()+"%","可用荷重")}</div>${winBtns()}</div>`; }
function waterPanel(){ return `<div class="win"><h3>💦 射水就位成功</h3>
  <p>車位留在<strong>倒塌區外</strong>、對準相對安全的<strong>建物轉角</strong>、平台完全置中後開砲；斷水、風向逆轉或通訊失效時，平台有明確回收路徑（教材 p.15、p.46）。</p>
  <div class="wstats">${stat(sim.time.toFixed(1)+"s","作業用時")}${stat(reachM().toFixed(1)+" m","水平伸距")}${stat("置中","平台狀態")}${stat(loadPct()+"%","可用荷重")}</div>${winBtns()}</div>`; }
function belowPanel(){ return `<div class="win"><h3>🌉 平台已達橋下邊坡</h3>
  <p style="color:var(--red);font-weight:600">⚠️ 教材紅字（p.19）：低於車位平面的救援屬特殊作業，<strong>本分隊 33 車實際無法操作</strong>——此為負仰角＋關節臂的能力示範，實務須改由具此能力之車輛執行。</p>
  <div class="wstats">${stat(sim.mainAng.toFixed(0)+"°","主臂仰角")}${stat(sim.jibAng.toFixed(0)+"°","關節臂角")}${stat(heightM().toFixed(1)+" m","平台高度")}${stat(loadPct()+"%","可用荷重")}</div>${winBtns()}</div>`; }
function retreatPanel(){ return `<div class="win"><h3>🛡️ 安全退離成功</h3>
  <p>風速逆轉破 12.5 m/s 停止線，你<strong>未超機械上限就主動撤離</strong>——平台是高處暴露位置，風向與流路變化會比車載警示更早傷人（教材 p.37）。落地後完成 PAR。</p>
  <div class="wstats">${stat(sim.time.toFixed(1)+"s","作業用時")}${stat((sim.wind).toFixed(1)+" m/s","退離時風速")}${stat("已全收","梯臂狀態")}</div>${winBtns()}</div>`; }
function wireWin(){
  const a=document.getElementById("winAgain"); if(a)a.onclick=()=>startScenario(sim.scen);
  const s=document.getElementById("winScen"); if(s)s.onclick=showScen;
  const q=document.getElementById("winQuiz"); if(q)q.onclick=startQuiz;
}

function update(dt){
  if(!sim) return;
  const p=sim.phase, sc=sim.scen;
  if(sim.t0===0 && (held.drive||p!=="position")) sim.t0=performance.now();
  sim.gust=Math.sin(performance.now()/1400)*0.5;

  if(p==="position"){
    if(held.drive){ sim.truckX+=held.drive*3.2*G.ppm*dt; sim.truckX=Math.max(G.driveMin,Math.min(G.driveMax,sim.truckX)); }
  }
  if(p==="balance"){
    sim.outrig=Math.min(1,sim.outrig+dt*0.9);
    if(sim.outrig>=1){ sim.tilt+=(0.10-sim.tilt)*Math.min(1,dt*2.2);
      if(Math.abs(sim.tilt-0.10)<0.005){ sim.tilt=0.10; sim.phase="operate"; renderControls(); renderSteps(); coach(); } }
  }
  if(p==="operate"){
    const negMin=sc.allowNeg?-55:0;
    if(held.rot){ sim.heading+=held.rot*35*dt; sim.heading=Math.max(-70,Math.min(70,sim.heading)); }
    if(held.ang){ sim.mainAng+=held.ang*15*dt; sim.mainAng=Math.max(negMin,Math.min(78,sim.mainAng)); }
    if(held.ext){ sim.mainLen+=held.ext*3.2*dt; sim.mainLen=Math.max(4,Math.min(24,sim.mainLen)); }
    if(held.jib){ sim.jibAng+=held.jib*28*dt; sim.jibAng=Math.max(-100,Math.min(25,sim.jibAng)); }
    sim.scba=Math.max(0,sim.scba-dt*0.55);
    // rising wind scenario
    if(sc.kind==="retreat"){
      if(!sim.exposed && (heightM()>7||inZone())) sim.exposed=true;
      if(sim.exposed) sim.wind+=sc.rise*dt;
      if(!sim.windEvent && sim.wind>=12.5){ sim.windEvent=true; renderControls(); }
    }
    const ab=document.getElementById("actBtn"); if(ab) ab.disabled=!actionEnabled();
    // coaching
    if(sc.kind==="retreat" && sim.windEvent) coach("🚨 風向逆轉、風速破 12.5 m/s！立即宣告『緊急退離』，停止任務、梯臂全收回收。","warn");
    else if((sim.wind+sim.gust)>=12.5) coach("⚠️ 風速達 12.5 m/s 停止線，停止展梯並準備安全回收（教材 p.27）。","warn");
    else if(!aligned()) coach(operateHint());
    else if(!clearsObstacles()) coach(sc.below?"⚠️ 梯臂／平台將撞護欄，先<strong>降負仰角越過</strong>再用關節臂下折。":"⚠️ 梯臂路徑將撞行道樹，先<strong>提高仰角</strong>跨越（水平瞄準）。","warn");
    else if(Math.abs(reachM())>11.6) coach("⚠️ 水平伸距過長、可用荷重下降，<strong>縮短伸距</strong>或重對轉台中心。","warn");
    else if(sc.kind==="water"&&inZone()&&Math.abs(sim.jibAng)>=6) coach("平台未置中，<strong>關節臂歸零</strong>使平台完全置中後才可開砲（水砲紅線）。","warn");
    else if(actionEnabled()) coach(sc.kind==="water"?"轉角對準、平台置中，可<strong>開始射水</strong>。":sc.kind==="below"?"平台已達橋下邊坡，可<strong>完成救援移載</strong>。":"平台已進入救援區，可<strong>完成救援移載</strong>。","ok");
    else coach();
  }
  if(p==="recover-run"){
    sim.mainLen+=(4-sim.mainLen)*Math.min(1,dt*2.0);
    sim.jibAng+=(0-sim.jibAng)*Math.min(1,dt*2.0);
    sim.mainAng+=((sim.scen.allowNeg?1:1)-sim.mainAng)*Math.min(1,dt*2.0);
    if(sim.mainLen<4.3 && Math.abs(sim.mainAng)<2 && Math.abs(sim.jibAng)<2){
      if(sim.retreating){ sim.time=(performance.now()-sim.t0)/1000; sim.success=true; sim.phase="done"; renderSteps();
        document.getElementById("simWin").innerHTML=retreatPanel(); wireWin();
        coach("✔ 平台安全落地，全員繫留、氣量與熱暴露評估，完成 PAR。","ok"); }
      else { sim.phase="done"; renderSteps(); coach("✔ 梯臂全收、轉台歸中、降至支架，腳架墊板收妥。完成 PAR，設備檢查後恢復待命。","ok"); }
    }
  }
  if(sim.t0) sim.time=(performance.now()-sim.t0)/1000;
}

/* ---- draw ---- */
function draw(){
  const P=palette(), {W,H,groundY}=G, sc=sim.scen;
  const sg=ctx.createLinearGradient(0,0,0,groundY); sg.addColorStop(0,P.sky1); sg.addColorStop(1,P.sky2);
  ctx.fillStyle=sg; ctx.fillRect(0,0,W,H);
  ctx.fillStyle=P.ground; ctx.fillRect(0,groundY,W,H-groundY);
  ctx.fillStyle=P.road; ctx.fillRect(0,groundY-2,(sc.below?G.bridgeEdge:G.driveMax+40),10);
  ctx.strokeStyle=P.lane; ctx.lineWidth=2; ctx.setLineDash([14,12]);
  ctx.beginPath();ctx.moveTo(0,groundY+3);ctx.lineTo((sc.below?G.bridgeEdge:G.driveMax+40),groundY+3);ctx.stroke(); ctx.setLineDash([]);
  if(sc.below) drawRiver(P); else drawBuilding(P);
  if(sc.collapse) drawCollapse(P);
  if(sc.tree) drawTree(P);
  if(sim.phase==="position") drawCone(P);
  drawZone(P);
  drawTruck(P);
  drawWind(P);
  drawMinimap(P);
}
function drawBuilding(P){
  const {W,groundY,ppm,bldLeft}=G, bw=W-bldLeft-6, top=groundY-22*ppm, sc=sim.scen;
  ctx.fillStyle=P.bld; ctx.fillRect(bldLeft,top,bw,groundY-top);
  ctx.fillStyle=P.bld2; ctx.fillRect(bldLeft,top,6,groundY-top);
  ctx.strokeStyle=P.edge; ctx.lineWidth=1.5; ctx.strokeRect(bldLeft,top,bw,groundY-top);
  const floors=7, fh=(groundY-top)/floors, cols=Math.max(2,Math.floor(bw/34));
  const litF = sc.kind==="water"?3:1;
  for(let f=0;f<floors;f++)for(let c=0;c<cols;c++){
    const wx=bldLeft+10+c*((bw-16)/cols), wy=top+8+f*fh, ww=(bw-16)/cols-8, wh=fh-14;
    ctx.fillStyle=(f===litF&&c===0)?P.winLit:P.win; ctx.fillRect(wx,wy,Math.max(6,ww),Math.max(6,wh));
  }
  const tx=G.targetX, ty=G.targetY;
  if(sc.kind==="water"){
    ctx.fillStyle=P.txt; ctx.font="600 12px 'Oswald',sans-serif"; ctx.textAlign="left";
    ctx.fillText("射水目標窗口",tx-6,ty-12);
    // downwind smoke on near (front) side
    ctx.fillStyle=P.smoke;
    for(let i=0;i<4;i++){ const yy=ty-6-i*10; ctx.beginPath(); ctx.ellipse(tx-18-i*3+Math.sin(performance.now()/500+i)*4,yy,14-i,9,0,0,7); ctx.fill(); }
  } else {
    ctx.fillStyle=P.edge; ctx.fillRect(tx-4,ty+6,26,4);
    ctx.strokeStyle=P.edge; ctx.lineWidth=2;
    for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(tx-4+i*8,ty+6);ctx.lineTo(tx-4+i*8,ty-6);ctx.stroke();}
    if(!sim.rescued) drawPerson(tx+8,ty+4,P,"#f2d0b0",true);
    ctx.fillStyle=P.txt; ctx.font="600 12px 'Oswald',sans-serif"; ctx.textAlign="left";
    ctx.fillText("6F 待救 · 2 人",tx-6,ty-12);
  }
}
function drawCollapse(P){
  const {groundY,colLeft,colRight}=G;
  ctx.save(); ctx.beginPath(); ctx.rect(colLeft,groundY-2,colRight-colLeft,10); ctx.clip();
  ctx.strokeStyle=P.hatch; ctx.lineWidth=2; ctx.globalAlpha=.7;
  for(let x=colLeft-12;x<colRight+12;x+=8){ ctx.beginPath();ctx.moveTo(x,groundY+10);ctx.lineTo(x+10,groundY-4);ctx.stroke(); }
  ctx.restore(); ctx.globalAlpha=1;
  ctx.fillStyle=P.hatch; ctx.font="600 10.5px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText("倒塌區·退路保留",(colLeft+colRight)/2,groundY+20);
}
function drawRiver(P){
  const {W,H,groundY,bridgeEdge,ppm}=G;
  ctx.fillStyle=P.river; ctx.fillRect(bridgeEdge,groundY+2,W-bridgeEdge,H-groundY);
  ctx.strokeStyle="rgba(255,255,255,.18)"; ctx.lineWidth=1.5;
  for(let i=0;i<4;i++){ const yy=groundY+16+i*14; ctx.beginPath();
    for(let x=bridgeEdge;x<W;x+=16) ctx.lineTo(x,yy+Math.sin(x/22+performance.now()/700+i)*2.4); ctx.stroke(); }
  // parapet (護欄)
  ctx.fillStyle=P.steel; ctx.fillRect(bridgeEdge-3,groundY-1.5*ppm,6,1.5*ppm);
  ctx.fillStyle=P.sub; ctx.font="500 10px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText("護欄",bridgeEdge,groundY-1.5*ppm-4);
  // far bank + target person below
  const tx=G.targetX, ty=G.targetY;
  ctx.fillStyle=P.ground; ctx.beginPath(); ctx.moveTo(tx-1.5*ppm,ty+1.2*ppm); ctx.lineTo(W,ty+1.2*ppm); ctx.lineTo(W,H); ctx.lineTo(tx-2.4*ppm,H); ctx.closePath(); ctx.fill();
  if(!sim.rescued) drawPerson(tx+4,ty+2,P,"#f2d0b0",true);
  ctx.fillStyle=P.txt; ctx.font="600 12px 'Oswald',sans-serif"; ctx.textAlign="left";
  ctx.fillText("橋下邊坡待救",tx-10,ty-10);
}
function drawTree(P){
  const cx=G.treeX, base=G.groundY, top=G.treeTop;
  ctx.fillStyle=P.trunk; ctx.fillRect(cx-3,top+18,6,base-top-18);
  ctx.fillStyle=P.tree; ctx.beginPath(); ctx.ellipse(cx,top+16,20,26,0,0,7); ctx.fill();
  ctx.fillStyle=P.tree2; ctx.beginPath(); ctx.ellipse(cx-8,top+22,12,16,0,0,7); ctx.fill();
  ctx.fillStyle=P.sub; ctx.font="500 11px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText("行道樹",cx,base+16);
}
function drawCone(P){
  const x=G.coneX, y=G.groundY;
  ctx.fillStyle=P.cone; ctx.beginPath(); ctx.moveTo(x,y-16); ctx.lineTo(x-8,y); ctx.lineTo(x+8,y); ctx.closePath(); ctx.fill();
  ctx.fillStyle="#fff"; ctx.fillRect(x-6,y-8,12,3);
  ctx.fillStyle=P.sub; ctx.font="500 10.5px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText("轉台中心",x,y+15);
  const dx=Math.abs(sim.truckX-x)/G.ppm;
  ctx.strokeStyle=dx<0.6?P.zone:P.cone; ctx.lineWidth=2; ctx.setLineDash([4,4]);
  ctx.beginPath();ctx.moveTo(sim.truckX,G.groundY-2);ctx.lineTo(sim.truckX,G.groundY-G.pivotYm*G.ppm-40);ctx.stroke();
  ctx.setLineDash([]);
}
function drawZone(P){
  if(sim.rescued||sim.scen.kind==="retreat"&&sim.retreating)return;
  const x=G.targetX,y=G.targetY, r=(sim.scen.kind==="water"?1.6:1.1)*G.ppm, pulse=8+Math.sin(performance.now()/300)*3;
  ctx.strokeStyle=P.zone; ctx.lineWidth=2; ctx.globalAlpha=.9;
  ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.stroke();
  ctx.globalAlpha=.25; ctx.beginPath();ctx.arc(x,y,r+pulse,0,7);ctx.stroke(); ctx.globalAlpha=1;
}
function drawWind(P){
  const x=G.W-70,y=42, w=(sim.wind+sim.gust);
  ctx.fillStyle=(w>=12.5?P.truck:w>=10?P.cone:P.zone);
  ctx.font="700 13px 'Oswald',sans-serif"; ctx.textAlign="right";
  ctx.fillText("風 "+w.toFixed(1)+" m/s",x+46,y);
  ctx.strokeStyle=P.sub;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-40,y+10);ctx.lineTo(x+40,y+10);ctx.stroke();
  ctx.beginPath();ctx.moveTo(x+40,y+10);ctx.lineTo(x+33,y+6);ctx.moveTo(x+40,y+10);ctx.lineTo(x+33,y+14);ctx.stroke();
}
function drawTruck(P){
  const p=pivot(), {ppm,groundY}=G, bx=sim.truckX;
  const bodyW=5.4*ppm, bodyH=1.7*ppm, wheelR=0.55*ppm, chassisY=groundY-0.55*ppm;
  if(sim.outrig>0){ const spread=2.6*ppm*sim.outrig;
    ctx.strokeStyle=P.steel; ctx.lineWidth=5;
    [-1,1].forEach(s=>{ ctx.beginPath();ctx.moveTo(bx+s*bodyW*0.32,chassisY-0.3*ppm);
      ctx.lineTo(bx+s*(bodyW*0.32+spread),groundY-2);ctx.stroke();
      ctx.fillStyle=P.pad; ctx.fillRect(bx+s*(bodyW*0.32+spread)-9,groundY-4,18,6); });
  }
  ctx.fillStyle="#1b1f22";
  [-1.8,-0.2,1.7].forEach(dx=>{ctx.beginPath();ctx.arc(bx+dx*ppm,groundY-wheelR,wheelR,0,7);ctx.fill();});
  ctx.fillStyle=P.truck; roundRect(bx-bodyW*0.5,chassisY-bodyH,bodyW,bodyH,6); ctx.fill();
  ctx.fillStyle=P.truckDk; ctx.fillRect(bx-bodyW*0.5,chassisY-0.35*ppm,bodyW,0.35*ppm);
  const cw=1.7*ppm,ch=1.4*ppm,cxx=bx-bodyW*0.5-cw+4;
  ctx.fillStyle=P.truck; roundRect(cxx,chassisY-ch,cw,ch,5); ctx.fill();
  ctx.fillStyle=P.glass; roundRect(cxx+4,chassisY-ch+4,cw-8,ch*0.5,3); ctx.fill();
  ctx.fillStyle=P.cone; ctx.fillRect(cxx+cw*0.3,chassisY-ch-4,cw*0.4,4);
  ctx.fillStyle=P.steel; roundRect(bx-0.9*ppm,chassisY-bodyH-0.5*ppm,1.8*ppm,0.7*ppm,3); ctx.fill();
  drawBoom(P);
  ctx.fillStyle="#fff"; ctx.font="700 11px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText("VEMA 32F",bx,chassisY-bodyH*0.45);
}
function drawSeg(a,b,wid,fill,stroke,secs){
  const ang=Math.atan2(b.y-a.y,b.x-a.x), len=Math.hypot(b.x-a.x,b.y-a.y);
  ctx.save(); ctx.translate(a.x,a.y); ctx.rotate(ang);
  for(let i=0;i<secs;i++){ const l=len*(1-i*0.24), w=wid*(1-i*0.16);
    ctx.fillStyle=i%2?stroke:fill; roundRect(0,-w/2,l,w,3); ctx.fill();
    ctx.strokeStyle=stroke; ctx.lineWidth=1; ctx.strokeRect(0,-w/2,l,w); }
  ctx.restore();
}
function drawBoom(P){
  const p=pivot(), m=mainTip(), t=tip();
  const hit=sim.phase==="operate"&&!clearsObstacles();
  drawSeg(p,m,0.55*G.ppm, hit?P.truck:P.boom, P.boomDk, 3);
  drawSeg(m,t,0.4*G.ppm, hit?P.truck:P.boomDk, P.boomDk, 2);
  // platform basket
  const bw=1.5*G.ppm,bh=1.0*G.ppm;
  ctx.fillStyle=P.steel; roundRect(t.x-4,t.y-bh*0.5,bw,bh,3); ctx.fill();
  ctx.strokeStyle=P.txt; ctx.lineWidth=1.5; ctx.strokeRect(t.x-4,t.y-bh*0.5,bw,bh);
  drawPerson(t.x+2,t.y-bh*0.5-1,P,P.truck,false);
  if(sim.rescued&&sim.scen.kind!=="water") drawPerson(t.x+bw*0.6,t.y-bh*0.5-1,P,"#f2d0b0",false);
  // water stream
  if(sim.watering){ ctx.strokeStyle=P.water; ctx.lineWidth=3; ctx.globalAlpha=.8;
    for(let i=0;i<3;i++){ ctx.beginPath(); ctx.moveTo(t.x+bw*0.5,t.y);
      ctx.quadraticCurveTo((t.x+G.targetX)/2, t.y-14-i*4, G.targetX+(Math.random()*6-3), G.targetY+(Math.random()*8-4)); ctx.stroke(); }
    ctx.globalAlpha=1; }
}
function drawPerson(x,footY,P,coat,wave){
  ctx.fillStyle=coat; ctx.beginPath(); ctx.arc(x,footY-14,3.2,0,7); ctx.fill();
  ctx.fillRect(x-3,footY-11,6,9);
  ctx.strokeStyle=coat;ctx.lineWidth=2;
  if(wave){ const w=Math.sin(performance.now()/200)*3; ctx.beginPath();ctx.moveTo(x,footY-9);ctx.lineTo(x+6,footY-15-w);ctx.stroke(); }
}
function drawMinimap(P){
  const x0=12,y0=12,w=146,h=100, cx=x0+38, cy=y0+h/2+4, R=Math.min(w-58,h-30);
  ctx.fillStyle=P.mmBg; ctx.globalAlpha=.92; roundRect(x0,y0,w,h,10); ctx.fill(); ctx.globalAlpha=1;
  ctx.strokeStyle=P.edge; ctx.lineWidth=1; roundRect(x0,y0,w,h,10); ctx.stroke();
  ctx.fillStyle=P.sub; ctx.font="600 9.5px 'Oswald',sans-serif"; ctx.textAlign="left"; ctx.fillText("俯視 · 轉台旋轉／掃掠區",x0+9,y0+14);
  ctx.setLineDash([3,3]); ctx.strokeStyle=P.edge; ctx.beginPath();ctx.arc(cx,cy,R,0,7);ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle=P.bld; ctx.fillRect(x0+w-24,y0+22,16,h-38);
  const A=a=>a*Math.PI/180;
  // wrong option dot for water (正面下風)
  if(sim.scen.kind==="water"){ const b0=A(0); ctx.fillStyle=P.truck; ctx.beginPath();ctx.arc(cx+Math.cos(b0)*R,cy-Math.sin(b0)*R,4,0,7);ctx.fill();
    ctx.font="600 8px 'Oswald'"; ctx.textAlign="left"; ctx.fillText("下風",cx+Math.cos(b0)*R+5,cy-Math.sin(b0)*R+3); }
  // target bearing dot
  const br=A(sim.scen.bearing), tx=cx+Math.cos(br)*R, ty=cy-Math.sin(br)*R;
  ctx.fillStyle=P.zone; ctx.beginPath();ctx.arc(tx,ty,4.5,0,7);ctx.fill();
  ctx.fillStyle=P.zone; ctx.font="600 8px 'Oswald'"; ctx.textAlign="left";
  ctx.fillText(sim.scen.kind==="water"?"轉角":"目標",tx+5,ty+3);
  // heading line
  const hr=A(sim.heading); ctx.strokeStyle=aligned()?P.zone:P.cone; ctx.lineWidth=2.6;
  ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(hr)*R,cy-Math.sin(hr)*R);ctx.stroke();
  ctx.fillStyle=P.truck; ctx.beginPath();ctx.arc(cx,cy,4,0,7);ctx.fill();
  ctx.fillStyle=aligned()?P.zone:P.cone; ctx.font="700 9.5px 'Oswald',sans-serif"; ctx.textAlign="center";
  ctx.fillText(aligned()?"● 已對準":"○ 旋轉對準",cx+18,y0+h-7);
}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}

/* ---- HUD ---- */
let hudTick=0;
function renderHUD(){
  const reach=reachM(),h=heightM(),ld=loadPct();
  const items=[
    {l:"伸距",v:reach.toFixed(1)+" m",bad:Math.abs(reach)>11.6},
    {l:"高度",v:h.toFixed(1)+" m"},
    {l:"仰角",v:Math.round(sim.mainAng)+"°"},
    {l:"關節",v:Math.round(sim.jibAng)+"°"},
    {l:"荷重",v:ld+"%",bad:ld<45,good:ld>=60},
    {l:"對準",v:aligned()?"OK":"偏",good:aligned(),bad:!aligned()},
    {l:"目標",v:(sim.rescued?"完成":distToTargetM().toFixed(1)+" m"),good:sim.rescued||inZone()},
  ];
  document.getElementById("hud").innerHTML=items.map(x=>`<div class="h ${x.bad?'bad':x.good?'good':''}"><small>${x.l}</small>${x.v}</div>`).join("");
}

function loop(t){
  if(!sim){return;}
  const dt=Math.min(0.05,(t-lastT)/1000||0); lastT=t;
  update(dt); draw();
  if(++hudTick%2===0){ renderHUD(); renderGauges(simDash()); renderSteps(); }
  raf=requestAnimationFrame(loop);
}
function startScenario(sc){
  sim=newScenario(sc); held.drive=held.ang=held.ext=held.rot=held.jib=0;
  document.getElementById("simTag").textContent=sc.tag;
  document.getElementById("simTitle").textContent=sc.name;
  show("sim"); document.getElementById("simWin").innerHTML="";
  layout(); coach(); renderControls(); renderSteps(); renderHUD();
  cancelAnimationFrame(raf); lastT=performance.now(); raf=requestAnimationFrame(loop);
  snap(); scrollTop();
}
function showScen(){
  stopSim(); show("scen"); idleGauges();
  document.getElementById("scenGrid").innerHTML=SCEN.map((s,i)=>
    `<button class="mode" data-scen="${i}"><div class="ic">${s.ic}</div><h3 style="font-size:16px">${s.name}</h3><p>${s.intro}</p><div class="go">${s.page} ▶</div></button>`).join("");
  document.querySelectorAll("#scenGrid [data-scen]").forEach(b=>b.onclick=()=>startScenario(SCEN[+b.dataset.scen]));
  snap(); scrollTop();
}
function stopSim(){ cancelAnimationFrame(raf); raf=null; sim=null; }

/* keyboard */
addEventListener("keydown",e=>{
  if(!sim||document.getElementById("screen-sim").hidden)return;
  const k=e.key.toLowerCase();
  if(sim.phase==="position"){ if(k==="arrowleft"||k==="a")held.drive=-1; if(k==="arrowright"||k==="d")held.drive=1; }
  if(sim.phase==="operate"){
    if(k==="w"||k==="arrowup")held.ang=1; if(k==="s"||k==="arrowdown")held.ang=-1;
    if(k==="d"||k==="arrowright")held.ext=1; if(k==="a"||k==="arrowleft")held.ext=-1;
    if(k==="q")held.rot=1; if(k==="e")held.rot=-1;
    if(k==="r")held.jib=1; if(k==="f")held.jib=-1;
  }
},{passive:true});
addEventListener("keyup",e=>{ const k=e.key.toLowerCase();
  if(["arrowleft","a"].includes(k)){held.drive=held.drive<0?0:held.drive;held.ext=held.ext<0?0:held.ext;}
  if(["arrowright","d"].includes(k)){held.drive=held.drive>0?0:held.drive;held.ext=held.ext>0?0:held.ext;}
  if(["w","arrowup"].includes(k))held.ang=held.ang>0?0:held.ang;
  if(["s","arrowdown"].includes(k))held.ang=held.ang<0?0:held.ang;
  if(k==="q")held.rot=held.rot>0?0:held.rot; if(k==="e")held.rot=held.rot<0?0:held.rot;
  if(k==="r")held.jib=held.jib>0?0:held.jib; if(k==="f")held.jib=held.jib<0?0:held.jib;
});
addEventListener("resize",()=>{ if(sim)layout(); });

/* ================= QUIZ (mode B) ================= */
const POINTS=12.5,N=8;
const LEVELS=[
 {title:"規範適用順位與六大技術紅線",focus:"教材 p.2、p.6、p.34 ｜ 三種來源各管一件事",dash:{wind:12.0,tilt:0.10,leg:120,scba:95},
  scenario:"你參考的德國通用雲梯車教材寫著「最大操作風速 22 m/s」，但眼前 VEMA 32F 的原廠手冊與車載顯示標示的停止線是 12.5 m/s。此刻風速計顯示 12.0 m/s、陣風偶爾拉高。",
  question:"當外國通用教材數值與 VEMA 原廠手冊衝突時，現場應以何者為準？",
  options:["以德國教材的 22 m/s 為準，代表本車還有很大操作餘裕","以 VEMA 原廠手冊／車載顯示的 12.5 m/s 為準，接近上限即準備停止回收","取兩者平均約 17 m/s 作為折衷操作標準","由現場最資深人員憑經驗判斷，數值僅供參考"],answer:1,
  analysis:`<p><strong>正確順位（教材 p.2）：</strong>型式銘牌、車載顯示與 VEMA 最新手冊 ＞ 本隊核定 SOP ＞ 國外雲梯車通用教材與一般經驗。</p><ul><li>德國教材的 <strong>22 m/s</strong> 是通用停止提醒，<strong>不是本車可用上限</strong>；VEMA 32F 採更嚴格的 <strong>12.5 m/s</strong>（p.27）。</li><li>達到或超過上限：<strong>停止任務並安全回收</strong>；雷雨一律不操作。</li></ul><blockquote>「最大 500 kg」是能力上限，<strong>不代表所有姿態都能使用</strong>。</blockquote>`},
 {title:"團隊編組與四眼原則",focus:"教材 p.4、p.41、p.43 ｜ 至少雙重覆核",dash:{wind:6.0,tilt:0.15,leg:145,scba:93},
  scenario:"轉台操作員看主控台螢幕，判斷荷重與範圍都在允許內，準備展梯。此時車長在車尾觀察地面，發現預定腳架落點旁有一處人孔蓋，判定 NO-GO。",
  question:"依「四眼原則」，操作員與車長判斷不一致時應如何處置？",
  options:["以操作員的主控台數據為準，繼續展梯","車長為現場指揮，直接要求操作員照命令展梯","任何一方判定 NO-GO 就先停止，重新評估地面與車位後才動作","先展梯到低角度測試，沒異常再繼續"],answer:2,
  analysis:`<p><strong>四眼原則（教材 p.4）：</strong>車長與操作員都要評估地面、腳架與車位，<strong>任何一方判定 NO-GO，就先停。</strong></p><blockquote>地面（U）：避開人孔、地下室頂板與軟弱回填區，離人孔／排水孔建議 <strong>≥ 0.5 m</strong>（p.26）。</blockquote><p>本題腳架壓力已達 145 kN（逼近 150 kN），加上人孔疑慮，<strong>停止重選位</strong>是唯一正解。</p>`},
 {title:"戰術定位與三種接近方式",focus:"教材 p.6、p.20–23、p.31 ｜ 轉台中心為戰術原點",dash:{wind:4.0,tilt:0.10,leg:110,scba:90},
  scenario:"六樓陽台有待救者，前方有一排行道樹與招牌。你要決定雲梯車停在哪裡，並選擇接近方式。",
  question:"關於「轉台中心（戰術原點）」與定位順序，何者正確？",
  options:["先把車停到看起來順的位置，再祈禱平台搆得到目標","從救援點向外估算必要伸距，標出轉台中心，再把車身引導進來覆核腳架與尾擺","轉台中心離目標越遠越安全，應盡量拉開水平伸距","只要在 500 kg 能力內，任何伸距與姿態都可放心使用"],answer:1,
  analysis:`<p><strong>定位原則（教材 p.6、p.31）：</strong>把轉台中心當「戰術原點」，<strong>從救援點向外估算伸距，而不是先停車再祈禱搆得到。</strong>縮短水平伸距＝更高可用荷重、更穩定。</p><p><strong>三種接近（p.20–23）：</strong>正面／水平瞄準（障礙上緣與目標重疊，再靠近約 2 m）／垂直瞄準（外牆、陽台、簷口排成一線，口訣「距障礙 1 米、50 公分、停止」）。</p>`},
 {title:"HAUS 否決檢核與 60 秒 GO／NO-GO",focus:"教材 p.24–29、p.38 ｜ 四次否決權",dash:{wind:8.0,tilt:0.18,leg:148,scba:88},
  scenario:"展梯前做最後檢核。地面看似平整，但你注意到腳架落點下方可能是地下室頂板，且旁邊有排水溝蓋。同時傾斜顯示 0.18°、單腳壓力 148 kN。",
  question:"HAUS 檢核中的「U」代表什麼、要確認哪些項目？",
  options:["U = Umgebung 環境，只需確認周圍有沒有圍觀民眾","U = Untergrund 地面，確認承載、坡度、人孔、溝蓋、地下室等能否安全傳力","U = Utility 管線，只要避開電線即可","U = Up 上空，確認梯身上方淨空與電線距離"],answer:1,
  analysis:`<p><strong>HAUS＝四次否決權（p.24），任一項不成立就重新選位：</strong></p><table><tr><th>碼</th><th>德文／中文</th><th>重點</th></tr><tr><td class="code">H</td><td>Hindernisse／障礙</td><td>電線、招牌、樹木、車輛、尾擺</td></tr><tr><td class="code">A</td><td>Abstände／距離</td><td>目標、腳架、梯身與旋轉淨空</td></tr><tr><td class="code">U</td><td>Untergrund／地面</td><td>承載、坡度、人孔、溝蓋、地下室</td></tr><tr><td class="code">S</td><td>Sicherheit／安全</td><td>風雨雷、煙熱、交通、視線、通訊</td></tr></table><blockquote>本題傾斜、單腳壓力都逼近紅線又疑似地下室頂板——<strong>NO-GO</strong>。不要用「應該可以」取代檢核。</blockquote>`},
 {title:"人命救援策略與四大救援模式",focus:"教材 p.8–12 ｜ 中山 33 車無梯身",dash:{wind:7.0,tilt:0.10,leg:130,scba:80},
  scenario:"A 面多樓層待救：三樓陽台一名民眾在濃煙旁劇烈咳嗽揮手求救，五樓兩名民眾暫時相對安全，四樓一群人尚未受直接威脅。本車為中山 33 車，無梯身。",
  question:"面對多個救援點，正確的救援排序與模式選擇原則為何？",
  options:["一律先救最高樓層，因為高樓最危險","依生命危險程度排序（立即威脅優先），一次停對能覆蓋最多高風險點的位置","誰喊最大聲先救誰","改用『大量人員經梯身下降』模式讓民眾自己爬下來"],answer:1,
  analysis:`<p><strong>救援排序看危險程度（p.8）：</strong>① 立即生命威脅 ② 危險區內人群 ③ 危險區內單一人員 ④ 鄰近未受威脅者。本題三樓緊鄰濃煙、立即威脅最高，<strong>依生命危險、不依樓層高低</strong>。</p><blockquote>模式 4「經梯身下降」屬特殊模式，<strong>本分隊 33 車無梯身，不適用</strong>；每次移載都要重算平台人員＋被救者＋裝備。</blockquote>`},
 {title:"火災射水戰術與水砲六項 NO-GO",focus:"教材 p.13–15、p.46 ｜ 水砲操作平台必須完全置中",dash:{wind:9.0,tilt:0.12,leg:140,scba:70},
  scenario:"大型建築火災需要平台水砲壓制。你完成 PPE 與供水準備，正要開砲時，發現平台偏向一側、尚未回到轉台中心，且下風排煙面正好在平台這一側。",
  question:"此刻準備平台水砲射水，最正確的處置是？",
  options:["先開砲壓制火勢，邊射邊把平台調正","立即停止，先把平台完全置中、並確認不在下風排煙側，再依供水順序開砲","直接套用德國教材 35 m B 線、約 70° 的數值操作","把水砲對準封閉屋頂單純降溫即可"],answer:1,
  analysis:`<p><strong>水砲紅線（p.15、p.34）：</strong>操作前<strong>確認平台置中</strong>；任務切換都要重新確認置中、荷重與範圍。</p><p><strong>射水前六項 NO-GO（p.46）：</strong>PPE／供水／協同／平台置中／位置（不在風下排煙側）／退路，少一項就先不要供水。</p><blockquote>不得直接套用德國 35 m B 線、70° 等他車型數值。</blockquote>`},
 {title:"PPE、繫留、SCBA 氣量管制與三區管制",focus:"教材 p.17、p.35–36、p.43 ｜ 90%／50% 管制",dash:{wind:10.0,tilt:0.15,leg:135,scba:50},
  scenario:"平台領隊回報個人 SCBA 殘壓已降到 50%，任務尚未完成，但低壓警報還沒響。地面詢問是否繼續。",
  question:"依本隊氣量管制，平台人員 SCBA 到 50% 時應如何處置？",
  options:["低壓警報還沒響，繼續完成任務","50% 即回報並回收；低壓警報是緊急預備氣，不是撤離提示","改吸平台固定供氣，個人 SCBA 可先卸下","等殘壓到 0% 前一刻再下降"],answer:1,
  analysis:`<p><strong>SCBA 管制（p.36）：</strong>出勤前 <strong>≥ 90%</strong>；<strong>50% 回報並回收</strong>。低壓警報是緊急預備氣，不是撤離提示。固定供氣僅供緊急使用，不能成為不背 SCBA 的理由。</p><p><strong>繫留：</strong>全身式吊帶＋核定安全繩，<strong>平台離地前完成</strong>（p.17、p.35）。<strong>三區管制</strong>：熱／暖／冷區都要有人負責，功能不得中斷（p.43）。</p>`},
 {title:"突發危害退離、PAR 清點與故障緊急回收",focus:"教材 p.37、p.44–45、p.47 ｜ 5 步驟緊急回收",dash:{wind:11.5,tilt:0.19,leg:142,scba:45},
  scenario:"平台在 A 面救援中，風向突然逆轉、濃煙掃向平台，同時主控台出現異常警報。已宣告緊急退離，準備依原廠順序安全回收梯臂。",
  question:"在「安全移動」階段，梯臂回收的正確動作順序為何？",
  options:["先旋轉轉台讓平台離開熱流，再慢慢縮回伸縮臂","先縮回伸縮臂，完全縮回後才旋轉，必要時手動調整平台平衡","直接使用緊急下降快速落地，取代一般回收程序","螢幕禁止動作時反覆重開機或旁路，強迫梯臂移動"],answer:1,
  analysis:`<p><strong>緊急回收 5 步驟（p.44）：</strong>① 緊急停止 ② 建立警戒 ③ 判讀錯誤（僅受訓操作員）④ <strong>安全移動：先縮回伸縮臂，完全縮回後才旋轉</strong> ⑤ 停用報修。</p><blockquote>禁止反覆強迫、重開機或旁路；緊急下降不是一般操作的替代。安全後完成 <strong>PAR</strong>，失聯升級 <strong>MAYDAY</strong>（p.37、p.45）。</blockquote>`},
];
let Q={level:0,score:0,records:{},submitted:false,picked:null};
function renderSegs(){document.getElementById("segs").innerHTML=LEVELS.map((_,i)=>{const done=Q.records[i]!==undefined;const cur=i===Q.level&&!done;return `<i class="${done?'done':cur?'cur':''}"></i>`}).join("")}
function renderScore(){document.getElementById("scoreNow").textContent=Q.score.toFixed(1)+" / 100"}
function renderLevel(){
  const i=Q.level,lv=LEVELS[i]; renderGauges(lv.dash); renderSegs(); renderScore();
  document.getElementById("lvNo").textContent=`第 ${i+1} 關 / ${N}`;
  document.getElementById("lvTitle").textContent=lv.title;
  document.getElementById("lvFocus").textContent=lv.focus;
  document.getElementById("lvScenario").textContent=lv.scenario;
  document.getElementById("lvQuestion").textContent=lv.question;
  const rec=Q.records[i],done=Q.submitted&&rec,marks=["A","B","C","D"];
  document.getElementById("lvOpts").innerHTML=lv.options.map((o,k)=>{let c="opt";if(done){if(k===lv.answer)c+=" correct";else if(k===rec.picked)c+=" wrong";}else if(Q.picked===k)c+=" sel";return `<button class="${c}" data-k="${k}" ${done?"disabled":""}><span class="mk">${marks[k]}</span><span class="tx">${o}</span></button>`}).join("");
  if(!done)document.querySelectorAll("#lvOpts .opt").forEach(b=>b.addEventListener("click",()=>{Q.picked=+b.dataset.k;renderLevel();snap();}));
  const resEl=document.getElementById("lvResult"),navEl=document.getElementById("lvNav");
  if(!done){resEl.innerHTML="";navEl.innerHTML=`<button class="btn block" id="submitBtn" type="button">✅&nbsp;&nbsp;送出判定</button>`;document.getElementById("submitBtn").onclick=submitQ;}
  else{const ok=rec.correct;
    resEl.innerHTML=`<div class="verdict ${ok?'right':'wrong'}"><span>${ok?'✔️ 判定正確！本關 +'+POINTS+' 分':'❌ 判定錯誤。'}</span>${ok?'':`<span class="x">你的選擇：${lv.options[rec.picked]}<br><b>正確處置：${lv.options[lv.answer]}</b></span>`}</div><details class="analysis" open><summary>📖 戰術解析與教材規範對照</summary><div class="content">${lv.analysis}</div></details>`;
    if(i<N-1){navEl.innerHTML=`<button class="btn block" id="nextBtn" type="button">➡&nbsp;&nbsp;進入下一關</button>`;document.getElementById("nextBtn").onclick=()=>{Q.level++;Q.submitted=false;Q.picked=null;renderLevel();snap();scrollTop();};}
    else{navEl.innerHTML=`<button class="btn block" id="reportBtn" type="button">📊&nbsp;&nbsp;查看結算報告</button>`;document.getElementById("reportBtn").onclick=()=>{show("result");renderResult();snap();scrollTop();};}
  }
}
function submitQ(){if(Q.picked===null){const nav=document.getElementById("lvNav");if(!document.getElementById("warnMsg"))nav.insertAdjacentHTML("afterbegin",`<div id="warnMsg" class="statusline warn" style="margin-bottom:12px">請先選擇一個處置方式，再送出。</div>`);return;}
  const i=Q.level,correct=Q.picked===LEVELS[i].answer;Q.records[i]={picked:Q.picked,correct};if(correct)Q.score+=POINTS;Q.submitted=true;renderLevel();snap();}
function rankOf(sc){if(sc>=100)return["gold","🏆 卓越戰術指揮官","全數命中！選位、否決、撤離皆到位，可擔任訓練示範與覆核角色。"];if(sc>=87.5)return["gold","🥇 資深雲梯戰術士","表現優異，僅少數細節待補強。"];if(sc>=75)return["mid","🥈 合格雲梯操作員","已具備現場基本判斷，建議針對錯題回訓。"];if(sc>=50)return["mid","🔶 待加強訓練","部分關鍵紅線與程序尚未穩固。"];return["low","🔴 需重新受訓","核心 NO-GO 與撤離觀念不足，建議重讀教材並重測。"];}
function renderResult(){idleGauges();const correct=Object.values(Q.records).filter(r=>r.correct).length;const[k,title,desc]=rankOf(Q.score);
  document.getElementById("resScore").innerHTML=`${Q.score.toFixed(Q.score%1?1:0)}<small> / 100</small>`;
  document.getElementById("resCorrect").textContent=`${correct} / ${N}`;
  document.getElementById("resTitle").textContent=title.replace(/^\S+\s/,"");
  const r=document.getElementById("resRank");r.className="rank "+k;r.innerHTML=`<h2>${title}</h2><p>${desc}</p>`;
  document.getElementById("resReview").innerHTML=LEVELS.map((lv,i)=>{const rec=Q.records[i],ok=rec&&rec.correct;const tick=ok?'<span class="tick ok">✅ 答對</span>':'<span class="tick no">❌ 答錯</span>';const pick=rec?(ok?`<div class="yourpick ok">你的選擇（正確）：${lv.options[rec.picked]}</div>`:`<div class="yourpick no">你的選擇：${lv.options[rec.picked]}</div><div class="rightans">正確處置：${lv.options[lv.answer]}</div>`):`<div class="rightans">正確處置：${lv.options[lv.answer]}</div>`;return `<details><summary>${tick}<span>第 ${i+1} 關｜${lv.title}</span></summary><div class="inner">${pick}<div class="analysis" style="margin-top:12px"><div class="content" style="padding:14px 16px">${lv.analysis}</div></div></div></details>`}).join("");
}
function startQuiz(){stopSim();Q={level:0,score:0,records:{},submitted:false,picked:null};show("quiz");renderLevel();snap();scrollTop();}

