/* Offline 3D edition. Metre-based world; Y up, boom azimuth about Y.
 * Mechanical limits and pressures are pedagogical approximations, not a load chart.
 */
const V3 = (x=0,y=0,z=0)=>new THREE.Vector3(x,y,z);
const radians = a=>a*Math.PI/180;
const R3 = {renderer:null,scene:null,camera:null,world:null,truck:null,boom:null,basket:null,
  view:'orbit',yaw:1.05,pitch:0.44,distance:45,tour:false,obstacles:[],materials:new Map(),smoke:[]};
const WORLD = {target:V3(),parking:-4,edge:2.5};
const clamp3=(v,a,b)=>Math.max(a,Math.min(b,v));
// Stowed like 中山33 (photos): first arm level over the cab on its rest, second arm folded back,
// platform on the deck cradle mid-body. Pivot at the turntable (x=0), 3.7 m up so the stowed
// platform (rails 1.1 m) fits under the first arm.
const PIVOT_Y3=3.7;
// Fold the 4 m jib so its tip lands 2.19 m ahead of the pivot, 2.37 m up (platform floor on the cradle).
function stowPose3(){const len=4,a=Math.asin((PIVOT_Y3-2.37)/len);return {mainLen:2.19+len*Math.cos(a),mainAng:0,jibAng:-(180-a*180/Math.PI),heading:180};}
// The bridge demo's imaginary 8 m jib stows folded at 4 m like the real truck and extends to its
// full length while unfolding (-150° to -110°).
function jibLen3(s=sim){if(!s.scen?.below)return s.jibLen;return 4+(s.jibLen-4)*clamp3((s.jibAng+150)/40,0,1);}
const STOW3=stowPose3();
const LEN_MIN3=5.9,LEN_MAX3=24,JIB_MIN3=-170,JIB_MAX3=25;
// Cab and body volumes of the truck model (truck-3d.js), relative to the turntable.
function truckBoxes3(s=sim){return {cab:new THREE.Box3(V3(s.truckX-6.9,.8,-1.25),V3(s.truckX-4.4,2.78,1.25)),body:new THREE.Box3(V3(s.truckX-4.4,.8,-1.25),V3(s.truckX+2.2,2.05,1.25))};}
const scenarioOriginal3=newScenario;
newScenario=function(sc){return Object.assign(scenarioOriginal3(sc),STOW3,{recoveryPlan:null,recoveryIndex:0,recoveryBlocked:false,visualTime:0});};
function mat3(color,metal=0){const key=color+':'+metal;if(!R3.materials.has(key))R3.materials.set(key,new THREE.MeshStandardMaterial({color,roughness:metal?0.4:0.83,metalness:metal}));return R3.materials.get(key);}
function box3(parent,x,y,z,w,h,d,color,metal=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat3(color,metal));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function cyl3(parent,x,y,z,r,h,color,rt=r){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,r,h,12),mat3(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
function beam3(parent,a,b,width,color){const m=box3(parent,0,0,0,width,1,width,color,0.5);setBeam3(m,a,b);return m;}
function setBeam3(m,a,b){m.position.copy(a).add(b).multiplyScalar(.5);m.scale.y=Math.max(.001,a.distanceTo(b));m.quaternion.setFromUnitVectors(V3(0,1,0),b.clone().sub(a).normalize());}
function line3(parent,points,color){const m=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color}));parent.add(m);return m;}
function label3(parent,text,x,y,z,color='#d9ecfa',scale=1){const c=document.createElement('canvas');c.width=768;c.height=96;const cx=c.getContext('2d');cx.fillStyle='#102131dd';cx.fillRect(0,0,c.width,c.height);cx.font='bold 36px "Microsoft JhengHei",sans-serif';cx.textAlign='center';cx.textBaseline='middle';cx.fillStyle=color;cx.fillText(text,384,48);const tex=new THREE.CanvasTexture(c);const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthTest:false}));s.position.set(x,y,z);s.scale.set(8*scale,scale,1);parent.add(s);return s;}
