function disposeWorld3(){if(!R3.world)return;R3.world.traverse(o=>{o.geometry?.dispose();if(o.isSprite||o.userData.disposeMaterial){o.material.map?.dispose();o.material.dispose();}if(o.isLine)o.material.dispose();});R3.targetRing?.material.dispose();R3.scene.remove(R3.world);}
function init3(){
 if(R3.renderer)return;
 try{R3.renderer=new THREE.WebGLRenderer({canvas:cv,antialias:true,preserveDrawingBuffer:true});}catch(e){document.getElementById('coachMsg').textContent='無法啟用 WebGL。請用支援硬體加速的 Chrome 或 Edge 開啟。';throw e;}
 R3.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));R3.renderer.shadowMap.enabled=true;R3.renderer.shadowMap.type=THREE.PCFSoftShadowMap;R3.renderer.outputColorSpace=THREE.SRGBColorSpace;R3.renderer.toneMapping=THREE.ACESFilmicToneMapping;R3.renderer.toneMappingExposure=1.25;
 R3.scene=new THREE.Scene();R3.scene.background=new THREE.Color('#96b5c9');R3.scene.fog=new THREE.Fog('#96b5c9',70,155);
 R3.scene.add(new THREE.HemisphereLight('#e6f4ff','#535e56',2.2));const sun=new THREE.DirectionalLight('#fff0d1',3.2);sun.position.set(-16,42,23);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-35,right:35,top:35,bottom:-35,near:1,far:100});sun.shadow.bias=-.0006;R3.scene.add(sun);
 R3.camera=new THREE.PerspectiveCamera(43,1,.15,240);
 let drag=null;
 cv.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};cv.setPointerCapture(e.pointerId);R3.view='orbit';R3.tour=false;syncViews3();});
 cv.addEventListener('pointermove',e=>{if(!drag)return;R3.yaw-=(e.clientX-drag.x)*.006;R3.pitch=clamp3(R3.pitch+(e.clientY-drag.y)*.005,.08,1.48);drag={x:e.clientX,y:e.clientY};});
 ['pointerup','pointercancel','lostpointercapture'].forEach(ev=>cv.addEventListener(ev,()=>drag=null));
 cv.addEventListener('wheel',e=>{e.preventDefault();R3.distance=clamp3(R3.distance*Math.exp(e.deltaY*.001),10,95);},{passive:false});
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{R3.view=b.dataset.view;R3.tour=false;syncViews3();});
 document.getElementById('tour').onclick=()=>{R3.tour=!R3.tour;R3.view='orbit';syncViews3();};
 document.getElementById('wide').onclick=()=>{document.body.classList.toggle('wide-view');layout();};
 new ResizeObserver(()=>{if(sim)layout();}).observe(cv);
}
