 for(const p of [-.56,.56]){const wheel=cyl3(g,p,.25,0,.25,.16,'#26302e');wheel.rotation.x=Math.PI/2;}
 box3(g,-.25,.62,0,.8,.44,.42,color);box3(g,-.25,.9,0,.75,.13,.44,'#353a36');
