  host.querySelector('button').onclick=()=>{sim.phase='done';sim.success=true;sim.parConfirmed=true;renderControls();renderSteps();coach('演練完成，PAR 與復歸檢核已確認。','ok');document.getElementById('simWin').innerHTML=retreatPanel();wireWin();};
