const updateBeforeDynamics3=update;
update=function(dt){
 if(!sim||document.hidden||!Number.isFinite(dt)||dt<=0)return;
 // Fixed-step integration keeps the illustrative spring response frame-rate stable.
 for(let remaining=Math.min(dt,.25);remaining>1e-8;remaining-=.01){
  const step=Math.min(.01,remaining),old=pose3(),phase=sim.phase;
  updateBeforeDynamics3(step);
  if(!sim)return;
  const angular=(sim.heading-old.heading)+(sim.mainAng-old.mainAng)*.4;
  sim.swayVelocity+=(-9*sim.sway-4*sim.swayVelocity)*step+angular*.0007;
  sim.sway=clamp3(sim.sway+sim.swayVelocity*step,-.015,.015);
  if(phase==='operate'&&Object.values(held).some(Boolean)&&JSON.stringify(old)===JSON.stringify(pose3()))sim.collisionCount++;
 }
};
