const ENV130_3=[[2.6,32.5],[5,32.6],[8,32.1],[10,31.5],[12.5,30.5],[15,28.4],[17.5,26.3],[19,24.7],[20,21.5],[20.6,20],[22,15],[23.3,10],[24.1,6],[24.1,3],[23.8,0],[22.5,-2],[20,-3.5],[17,-4.3],[15,-4.4],[9,-4.3],[5,-3],[3.8,-.5],[3.8,2.5],[2.9,4.2],[1.9,7],[.5,8.5],[-.4,10],[.3,17],[1.1,24],[2,30]];
// Load settings (04 p15): persons → max cage load. Heavier settings pull the outer reach in.
const LOAD_SETTINGS3=[{persons:1,kg:130,reach:1},{persons:2,kg:250,reach:.95},{persons:4,kg:370,reach:.91},{persons:5,kg:500,reach:.87}];
const TILT_LIMIT3=.3,TILT_COURSE3=.2;// manual: lift allowed within ±0.3°; course material red line ±0.2°
const CAB_SLOW3=2.5,CAB_STOP3=1;// cab protection zone (06 p56): slow, then stop moving toward the cab
