function personsOnPlatform3(){return 1+(sim?.rescued&&sim.scen.kind!=='water'?1:0);}
function loadSetting3(){const n=personsOnPlatform3();return LOAD_SETTINGS3.find(s=>s.persons>=n)||LOAD_SETTINGS3[3];}
function actualLoadKg3(){return personsOnPlatform3()*90;}// 90 kg per person incl. PPE/SCBA (illustrative)
function envelope3(setting=loadSetting3()){if(!envCache3.has(setting.kg))envCache3.set(setting.kg,ENV130_3.map(([r,h])=>[r>3?3+(r-3)*setting.reach:r,h]));return envCache3.get(setting.kg);}
// Signed distance to the envelope edge: positive inside, negative outside.
function envMargin3(r,h,poly=envelope3()){let inside=false,best=Infinity;
 for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [x1,y1]=poly[j],[x2,y2]=poly[i];
  if((y2>h)!==(y1>h)&&r<(x1-x2)*(h-y2)/(y1-y2)+x2)inside=!inside;
  const dx=x2-x1,dy=y2-y1,t=Math.max(0,Math.min(1,((r-x1)*dx+(h-y1)*dy)/(dx*dx+dy*dy||1)));best=Math.min(best,Math.hypot(r-x1-t*dx,h-y1-t*dy));}
 return inside?best:-best;}
// 橋下為概念展示，使用假想長臂，不套用原廠範圍。二臂摺疊收車（< -100°）時平台在車上托架，尚未進入作業範圍。
function envApplies3(s=sim){return !s.scen.below&&s.jibAng>=-100;}
function poseState3(pose){const s={...sim,...pose},j=joints3(s),reach=Math.hypot(j.t.x-j.p.x,j.t.z-j.p.z);
 const cab=truckBoxes3(s).cab,mid=j.m.clone().add(j.t).multiplyScalar(.5);
 return {reach,height:j.t.y,margin:envMargin3(reach,j.t.y),cab:Math.min(cab.distanceToPoint(j.t),cab.distanceToPoint(mid))};}
// Pure check used by both the motion gate and the on-screen direction arrows.
function limitCheck3(from,to){
 const a=poseState3(from),b=poseState3(to);let slow=1,reason=null;
 if(envApplies3({...sim,...to})){
  if(b.margin<0&&b.margin<a.margin-1e-6)return {ok:false,reason:'envelope',a,b};
  if(b.margin<ENV_SLOW3&&b.margin<a.margin-1e-6){slow=Math.min(slow,.4);reason='nearEdge';}
 }
 if(b.cab<CAB_STOP3&&b.cab<a.cab-1e-6)return {ok:false,reason:'cab',a,b};
 if(b.cab<CAB_SLOW3&&b.cab<a.cab-1e-6){slow=Math.min(slow,.35);reason=reason||'cabZone';}
 return {ok:true,slow,reason,a,b};
}
const motionClearBeforeLimits3=motionClear3;
motionClear3=function(from,to){
 if(!motionClearBeforeLimits3(from,to)){if(sim.phase==='operate'){LIMIT3.reason='collision';LIMIT3.at=performance.now();}return false;}
 // Automated recovery follows its own planned path; the manual limits gate operator input only.
 if(sim.phase!=='operate')return true;
 const c=limitCheck3(from,to);
 if(!c.ok){LIMIT3.reason=c.reason;LIMIT3.at=performance.now();return false;}
 if(c.slow<1){// The system decelerates near limits (06 p55–56): apply only part of this step.
  for(const k of Object.keys(STOW3))sim[k]=from[k]+(to[k]-from[k])*c.slow;LIMIT3.slowedAt=performance.now();}
 return true;
};
// Arrow colours for the screen: green allowed, yellow slowed, red blocked (06 p55).
function arrowState3(axis,sign){
 if(!sim||sim.phase!=='operate'||sim.consoleStopped)return 'block';
 const emergency=sim.wind+sim.gust>=12.5||sim.scba<=50;if(emergency&&!(axis==='mainLen'&&sign<0))return 'block';
 const from=pose3(),to={...from},step={mainAng:1.5,mainLen:.3,heading:1.5,jibAng:2}[axis];to[axis]+=sign*step;
 const range={mainAng:[sim.scen.allowNeg?-55:0,78],mainLen:[Math.min(LEN_MIN3,sim.mainLen),LEN_MAX3],heading:[-180,180],jibAng:[Math.min(JIB_MIN3,sim.jibAng),JIB_MAX3]}[axis];
 if(to[axis]<range[0]||to[axis]>range[1])return 'block';
 if(!motionClearBeforeLimits3(from,to))return 'block';
 const c=limitCheck3(from,to);return !c.ok?'block':c.slow<1?'slow':'ok';
}
function limitStatus3(){
 const now=performance.now(),s=poseState3(pose3()),recent=now-LIMIT3.at<1200;
 const applies=envApplies3();
 return {setting:loadSetting3(),actual:actualLoadKg3(),persons:personsOnPlatform3(),margin:s.margin,applies,cabDist:s.cab,
  envBlocked:applies&&((recent&&LIMIT3.reason==='envelope')||s.margin<0),nearEdge:applies&&s.margin>=0&&s.margin<ENV_SLOW3,
  cabBlocked:recent&&LIMIT3.reason==='cab',cabZone:s.cab<CAB_SLOW3,collision:recent&&LIMIT3.reason==='collision'};
}
// Coaching text replaces the generic "路徑受阻" for limit stops.
const updateBeforeLimits3=update;
update=function(dt){const before=LIMIT3.at;updateBeforeLimits3(dt);if(!sim||sim.phase!=='operate'||LIMIT3.at===before)return;
 if(LIMIT3.reason==='envelope')coach('已達作業範圍極限（原廠範圍圖，'+loadSetting3().kg+' kg 設定）：方向箭頭轉紅，請收回伸縮臂或升高第一臂。','warn');
 if(LIMIT3.reason==='cab')coach('車頭保護範圍：平台接近駕駛室，往車頭方向的動作已停止。請升高第一臂或轉台離開車頭。','warn');
};
// Tilt: manual allows lift within ±0.3°; the course's ±0.2° stays as the amber line.
tiltStat=function(v){v=Math.abs(v);return v>=TILT_LIMIT3?'red':v>=TILT_COURSE3?'amber':'ok';};
const actionBeforeLimits3=actionEnabled;
actionEnabled=function(){if(!sim||sim.phase!=='operate')return false;const tilt=sim.tilt;
 // Earlier checks hard-code the course's 0.2°; evaluate them with tilt inside that band, then apply the 0.3° limit.
 if(Math.abs(tilt)>=TILT_LIMIT3)return false;sim.tilt=Math.sign(tilt)*Math.min(Math.abs(tilt),.19);try{return actionBeforeLimits3();}finally{sim.tilt=tilt;}};
const hudBeforeLimits3=renderHUD;
renderHUD=function(){hudBeforeLimits3();if(!sim)return;for(const item of document.querySelectorAll('#hud .h'))if(item.querySelector('small')?.textContent==='可用荷重'){const s=loadSetting3();item.innerHTML='<small>平台載重設定</small>'+s.kg+' kg（'+s.persons+' 人）';}};

