while(sceneStage3.firstChild)sceneViewport3.append(sceneStage3.firstChild);
sceneStage3.append(sceneViewport3,consolePanel3);
const consoleInputs3=new Map();
const consoleReleases3=[];
let consoleSlow3=false,consoleSim3=null;
function consoleReady3(){return sim?.phase==='operate'&&!sim.consoleStopped;}
function clearConsole3(){for(const release of consoleReleases3)release();for(const axis of ['ang','jib','ext','rot'])if([...consoleInputs3.values()].some(v=>v.axis===axis))held[axis]=0;consoleInputs3.clear();consolePanel3.querySelectorAll('.bronto-knob').forEach(k=>k.style.transform='translate(-50%,-50%)');consolePanel3.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));}
const consoleResetOriginal3=resetHeld3;
resetHeld3=function(){consoleResetOriginal3();clearConsole3();};
window.addEventListener('blur',()=>resetHeld3());
document.addEventListener('visibilitychange',()=>resetHeld3());
function setConsoleInput3(id,axis,value){const old=consoleInputs3.get(id);if(old&&old.axis!==axis)held[old.axis]=0;consoleInputs3.set(id,{axis,value});held[axis]=value;}
function releaseConsoleInput3(id){const old=consoleInputs3.get(id);consoleInputs3.delete(id);if(old){const rest=[...consoleInputs3.values()].filter(v=>v.axis===old.axis).pop();held[old.axis]=rest?.value||0;}}
function wireConsoleStick3(id,vertical,horizontal,verticalSign=1){
 const pad=document.getElementById(id),knob=pad.querySelector('i');let pointer=null;
 const move=e=>{if(e.pointerId!==pointer)return;if(!consoleReady3()){release(e);return;}const r=pad.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2);knob.style.transform=`translate(calc(-50% + ${clamp3(x,-1,1)*22}px),calc(-50% + ${clamp3(y,-1,1)*22}px))`;if(Math.max(Math.abs(x),Math.abs(y))<.18){releaseConsoleInput3(id);return;}const useY=Math.abs(y)>=Math.abs(x);setConsoleInput3(id,useY?vertical:horizontal,((useY?y:x)<0?1:-1)*(useY?verticalSign:1));};
 const release=e=>{if(pointer!==null&&e.pointerId!==undefined&&e.pointerId!==pointer)return;releaseConsoleInput3(id);pointer=null;knob.style.transform='translate(-50%,-50%)';};
 consoleReleases3.push(()=>release({}));
 pad.addEventListener('pointerdown',e=>{if(!consoleReady3()||pointer!==null||e.button>0)return;e.preventDefault();pointer=e.pointerId;pad.setPointerCapture(pointer);move(e);});pad.addEventListener('pointermove',move);['pointerup','pointercancel','lostpointercapture'].forEach(type=>pad.addEventListener(type,release));
 window.addEventListener('blur',()=>release({}));document.addEventListener('visibilitychange',()=>release({}));
}
wireConsoleStick3('brontoLeftStick','ang','jib',-1);wireConsoleStick3('brontoRightStick','ext','rot');
consolePanel3.querySelectorAll('[data-console-hold]').forEach(b=>{
 const code=b.dataset.consoleHold,axis=code.slice(0,-2),dir=code.endsWith('+1')?1:-1;let pointer=null;
 const start=e=>{if(!consoleReady3())return;e.preventDefault();if(e.pointerId!==undefined){pointer=e.pointerId;if(b.hasPointerCapture&&!b.hasPointerCapture(pointer)){try{b.setPointerCapture(pointer);}catch{}}}setConsoleInput3(code,axis,dir);b.classList.add('pressed');};
 const end=()=>{releaseConsoleInput3(code);pointer=null;b.classList.remove('pressed');};
 consoleReleases3.push(end);
 b.addEventListener('pointerdown',start);['pointerup','pointercancel','lostpointercapture','blur'].forEach(t=>b.addEventListener(t,end));b.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)&&!e.repeat)start(e);});b.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key))end();});
});
document.getElementById('brontoCollapse').onclick=e=>{resetHeld3();const collapsed=consolePanel3.classList.toggle('collapsed');e.target.textContent=collapsed?'展開控制台':'收合控制台';e.target.setAttribute('aria-expanded',!collapsed);layout();};
document.getElementById('brontoSlow').onclick=()=>{consoleSlow3=!consoleSlow3;syncConsole3();};
document.getElementById('brontoStop').onclick=()=>{if(!sim)return;resetHeld3();sim.consoleStopped=!sim.consoleStopped;syncConsole3();};
document.getElementById('brontoCenter').onclick=()=>{if(consoleReady3()&&sim.scen.kind==='water'){sim.platformYaw=0;syncConsole3();}};
document.getElementById('brontoAction').onclick=()=>{if(consoleReady3()&&actionEnabled())doAction();};
function syncConsole3(){
 if(!sim)return;if(consoleSim3!==sim){resetHeld3();consoleSim3=sim;consoleSlow3=false;}
 const ready=consoleReady3(),phaseNames={position:'選位中',support:'支撐確認',balance:'展開腳架',operate:'手動操作',recover:'任務完成', 'recover-run':'回收中','recovery-blocked':'回收受阻',par:'PAR 確認',done:'演練完成'};
 document.getElementById('brontoState').textContent=sim.consoleStopped?'動作已停止':phaseNames[sim.phase]||sim.phase;
 document.getElementById('brontoLamp').style.color=sim.consoleStopped?'#ff6655':ready?'#a5e96e':'#f1c362';
 document.getElementById('brontoReadings').innerHTML=`<span>高度<b>${heightM().toFixed(1)}<small> m</small></b></span><span>伸距<b>${reachM().toFixed(1)}<small> m</small></b></span><span>第一臂<b>${sim.mainAng.toFixed(0)}°</b></span><span>第二臂<b>${sim.jibAng.toFixed(0)}°</b></span><span>轉台<b>${sim.heading.toFixed(0)}°</b></span><span>風速<b>${(sim.wind+sim.gust).toFixed(1)}<small> m/s</small></b></span>`;
 let message=sim.consoleStopped?'按「解除停止」後重新操作':!ready?'請依下方流程完成當前步驟':sim.scen.kind==='water'?(Math.abs(sim.platformYaw)>=.5?'射水前請先平台置中':!sim.waterChecks?'請完成下方六項射水確認':actionEnabled()?'射水條件已符合':'調整臂架接近目標'):actionEnabled()?'已到達任務位置':'調整臂架接近目標';
 document.getElementById('brontoMessage').textContent=message;
 consolePanel3.querySelectorAll('[data-console-hold]').forEach(b=>b.disabled=!ready);
 consolePanel3.querySelectorAll('.bronto-pad').forEach(p=>p.setAttribute('aria-disabled',!ready));
 const action=document.getElementById('brontoAction');action.textContent=sim.scen.kind==='water'?'開始射水':sim.scen.kind==='retreat'?'緊急退離':'完成救援';action.disabled=!ready||!actionEnabled();
 document.getElementById('brontoCenter').disabled=!ready||sim.scen.kind!=='water';
 const stop=document.getElementById('brontoStop');stop.textContent=sim.consoleStopped?'解除停止':'停止動作';stop.setAttribute('aria-pressed',!!sim.consoleStopped);
 document.getElementById('brontoSlow').setAttribute('aria-pressed',consoleSlow3);
}
const consoleUpdateOriginal3=update;
update=function(dt){if(sim?.consoleStopped){resetHeld3();return;}const axes=['ang','jib','ext','rot'],saved={};if(consoleSlow3&&sim?.phase==='operate')for(const a of axes){saved[a]=held[a];held[a]*=.35;}try{consoleUpdateOriginal3(dt);}finally{for(const a of Object.keys(saved))if(held[a]!==0)held[a]=saved[a];}if(sim?.phase!=='operate')clearConsole3();};
