draw=function(){consoleDrawOriginal3();if(performance.now()-consoleLastPaint3>100){syncConsole3();consoleLastPaint3=performance.now();}};
const consoleControlsOriginal3=renderControls;
renderControls=function(){resetHeld3();consoleControlsOriginal3();syncConsole3();};

